const safeDecodeSVG = (str: string): string => {
  if (!str) return '';
  try {
    return decodeURIComponent(str);
  } catch (e) {
    return str;
  }
};

export const CITY_MAP: Record<string, string> = {
  "MU": "Mumbai",
  "DL": "Delhi",
  "BL": "Bangalore",
  "HY": "Hyderabad",
  "PU": "Pune",
  "CH": "Chennai",
  "KO": "Kolkata",
  "MA": "Mancherial"
};

export const CATEGORY_MAP: Record<string, string> = {
  "P": "Payment & Refund",
  "S": "Safety & SOS Alert",
  "D": "Driver Verification",
  "G": "General Enquiry",
  "T": "Technical Issue"
};

export interface IdSegment {
  label: string;
  code: string;
  color: string;
  meaning: string;
}

export interface IdBreakdown {
  entity: string;
  prefix: string;
  description: string;
  segments: IdSegment[];
}

export const parseIdForBreakdown = (id: string): IdBreakdown | null => {
  if (!id) return null;
  const upper = id.toUpperCase().trim().replace(/^#/, "");
  
  if (upper.startsWith("USR")) {
    const year = upper.substring(3, 5);
    const city = upper.substring(5, 7);
    const random = upper.substring(7);
    return {
      entity: "Legacy User Token / Converted 2-ID Account",
      prefix: "USR",
      description: "Legacy core user account token mapped into the 2-ID system (Rider ID: RID... + Driver ID: DRV...).",
      segments: [
        { label: "Entity Prefix", code: "USR", color: "bg-slate-800 text-white border-slate-800 font-bold", meaning: "Legacy single user token (mapped to RID & DRV)." },
        { label: "Signup Year", code: year, color: "bg-slate-100 text-slate-800 border-slate-200", meaning: `Registered in 20${year || '26'}.` },
        { label: "Base City Hub", code: city, color: "bg-slate-100 text-slate-800 border-slate-200", meaning: `Primary location hub: ${CITY_MAP[city] || 'Operational Hub'}.` },
        { label: "Unique Code", code: random, color: "bg-slate-50 text-slate-700 border-slate-200", meaning: "8-character uppercase secure alphanumeric string." }
      ]
    };
  }

  if (upper.startsWith("DRV")) {
    const year = upper.substring(3, 5);
    const city = upper.substring(5, 7);
    const random = upper.substring(7);
    return {
      entity: "Driver Registry ID",
      prefix: "DRV",
      description: "Driver account token tracking registration year and operational city hub.",
      segments: [
        { label: "Entity Prefix", code: "DRV", color: "bg-slate-900 text-white border-slate-900 font-bold", meaning: "Identifies a Driver registry token." },
        { label: "Registry Year", code: year, color: "bg-slate-100 text-slate-800 border-slate-200", meaning: `Registered in 20${year || '26'}.` },
        { label: "City Hub", code: city, color: "bg-slate-100 text-slate-800 border-slate-200", meaning: `Base location hub: ${CITY_MAP[city] || 'Operational Hub'}.` },
        { label: "Unique Code", code: random, color: "bg-slate-50 text-slate-700 border-slate-200", meaning: "8-character uppercase secure alphanumeric string." }
      ]
    };
  }
  
  if (upper.startsWith("RID")) {
    const year = upper.substring(3, 5);
    const city = upper.substring(5, 7);
    const random = upper.substring(7);
    return {
      entity: "Rider Account ID",
      prefix: "RID",
      description: "Rider user identity token mapping initial signup year and registration city.",
      segments: [
        { label: "Entity Prefix", code: "RID", color: "bg-slate-900 text-white border-slate-900 font-bold", meaning: "Identifies a Rider account." },
        { label: "Signup Year", code: year, color: "bg-slate-100 text-slate-800 border-slate-200", meaning: `Signed up in 20${year || '26'}.` },
        { label: "Registration City", code: city, color: "bg-slate-100 text-slate-800 border-slate-200", meaning: `Initial signup city: ${CITY_MAP[city] || 'Operational Hub'}.` },
        { label: "Unique Code", code: random, color: "bg-slate-50 text-slate-700 border-slate-200", meaning: "8-character uppercase secure alphanumeric string." }
      ]
    };
  }
  
  if (upper.startsWith("TRP")) {
    const chunk = upper.substring(3, 5);
    const isLocal = /^\d+$/.test(chunk);
    if (isLocal) {
      const year = chunk;
      const city = upper.substring(5, 7);
      const random = upper.substring(7);
      return {
        entity: "Local Segment Ride ID",
        prefix: "TRP",
        description: "Intra-city booking token tracking transaction year and local service city.",
        segments: [
          { label: "Entity Prefix", code: "TRP", color: "bg-slate-900 text-white border-slate-900 font-bold", meaning: "Identifies a Ride/Transit booking." },
          { label: "Booking Year", code: year, color: "bg-slate-100 text-slate-800 border-slate-200", meaning: `Booked in 20${year || '26'}.` },
          { label: "Transit City", code: city, color: "bg-slate-100 text-slate-800 border-slate-200", meaning: `Operated in: ${CITY_MAP[city] || 'Operational City'}.` },
          { label: "Unique Code", code: random, color: "bg-slate-50 text-slate-700 border-slate-200", meaning: "8-character uppercase secure alphanumeric string." }
        ]
      };
    } else {
      const startCity = chunk;
      const endCity = upper.substring(5, 7);
      const random = upper.substring(7);
      return {
        entity: "Intercity Route Ride ID",
        prefix: "TRP",
        description: "Long-distance multi-city transit token encoding departure origin and arrival route direction.",
        segments: [
          { label: "Entity Prefix", code: "TRP", color: "bg-slate-900 text-white border-slate-900 font-bold", meaning: "Identifies an Intercity Ride booking." },
          { label: "Origin Hub", code: startCity, color: "bg-slate-100 text-slate-800 border-slate-200", meaning: `Departs from: ${CITY_MAP[startCity] || startCity}.` },
          { label: "Destination Hub", code: endCity, color: "bg-slate-100 text-slate-800 border-slate-200", meaning: `Arrives at: ${CITY_MAP[endCity] || endCity}.` },
          { label: "Unique Code", code: random, color: "bg-slate-50 text-slate-700 border-slate-200", meaning: "8-character uppercase secure alphanumeric string." }
        ]
      };
    }
  }
  
  if (upper.startsWith("TXN")) {
    const year = upper.substring(3, 5);
    const city = upper.substring(5, 7);
    const random = upper.substring(7);
    return {
      entity: "Digital Ledger Transaction ID",
      prefix: "TXN",
      description: "Settlement ledger token mapping financial activity year and transaction city hub.",
      segments: [
        { label: "Entity Prefix", code: "TXN", color: "bg-slate-900 text-white border-slate-900 font-bold", meaning: "Identifies a digital financial ledger transaction." },
        { label: "Settlement Year", code: year, color: "bg-slate-100 text-slate-800 border-slate-200", meaning: `Cleared in 20${year || '26'}.` },
        { label: "Regional Settlement", code: city, color: "bg-slate-100 text-slate-800 border-slate-200", meaning: `Tax/Settlement region: ${CITY_MAP[city] || 'Operational Hub'}.` },
        { label: "Unique Code", code: random, color: "bg-slate-50 text-slate-700 border-slate-200", meaning: "8-character uppercase secure alphanumeric string." }
      ]
    };
  }
  
  if (upper.startsWith("TKT")) {
    const year = upper.substring(3, 5);
    const category = upper.substring(5, 6);
    const random = upper.substring(6, 14);
    const checksum = upper.substring(14);
    return {
      entity: "Algorithmic Ticket ID",
      prefix: "TKT",
      description: "Support ticket token embedding category classification and mathematical checksum to secure ticket integrity.",
      segments: [
        { label: "Entity Prefix", code: "TKT", color: "bg-slate-900 text-white border-slate-900 font-bold", meaning: "Identifies a Customer Support Ticket." },
        { label: "Creation Year", code: year, color: "bg-slate-100 text-slate-800 border-slate-200", meaning: `Created in 20${year || '26'}.` },
        { label: "Ticket Category", code: category, color: "bg-slate-100 text-slate-800 border-slate-200", meaning: `Issue Class: ${CATEGORY_MAP[category] || 'General Enquiry'}.` },
        { label: "Unique Code", code: random, color: "bg-slate-50 text-slate-700 border-slate-200", meaning: "8-character uppercase secure alphanumeric string." },
        { label: "Checksum Validation", code: checksum, color: "bg-slate-200 text-slate-900 border-slate-300 font-bold", meaning: `Algorithmic checksum digit (${checksum || 'X'}) computed from prior segments to prevent indexing typos.` }
      ]
    };
  }

  if (upper.startsWith("CHT")) {
    const year = upper.substring(3, 5);
    const city = upper.substring(5, 7);
    const random = upper.substring(7);
    return {
      entity: "Live Chat Conversation ID",
      prefix: "CHT",
      description: "Encrypted live messaging conversation token tracking origin year and regional routing hub.",
      segments: [
        { label: "Entity Prefix", code: "CHT", color: "bg-slate-900 text-white border-slate-900 font-bold", meaning: "Identifies a live support or trip chat thread." },
        { label: "Creation Year", code: year, color: "bg-slate-100 text-slate-800 border-slate-200", meaning: `Initiated in 20${year || '26'}.` },
        { label: "Routing City", code: city, color: "bg-slate-100 text-slate-800 border-slate-200", meaning: `Regional chat hub: ${CITY_MAP[city] || 'Operational Hub'}.` },
        { label: "Unique Code", code: random, color: "bg-slate-50 text-slate-700 border-slate-200", meaning: "8-character uppercase secure alphanumeric string." }
      ]
    };
  }
  
  return null;
};

export const BackendCheckbox: React.FC<{
  checked: boolean;
  onChange: (checked: boolean) => void;
  label?: React.ReactNode;
  sublabel?: string;
  disabled?: boolean;
  id?: string;
  className?: string;
}> = ({ checked, onChange, label, sublabel, disabled = false, id, className = '' }) => {
  return (
    <label className={cn(
      "flex items-center gap-3 p-2.5 rounded-xl border border-slate-200/80 cursor-pointer select-none transition-all",
      checked ? "bg-amber-50/50 border-amber-300" : "bg-white hover:bg-slate-50",
      disabled && "opacity-50 cursor-not-allowed",
      className
    )}>
      <button
        type="button"
        id={id}
        disabled={disabled}
        onClick={(e) => {
          e.stopPropagation();
          if (!disabled) onChange(!checked);
        }}
        className={cn(
          "w-5 h-5 rounded-md border transition-all flex items-center justify-center shrink-0 cursor-pointer focus:outline-none focus:ring-2 focus:ring-amber-400 focus:ring-offset-1",
          checked
            ? "bg-amber-400 border-amber-500 text-slate-950 shadow-xs"
            : "bg-white border-slate-300 hover:border-amber-400"
        )}
      >
        {checked && <Check size={14} className="stroke-[3]" />}
      </button>
      {(label || sublabel) && (
        <div className="text-xs">
          {label && <span className="font-bold text-slate-900 block">{label}</span>}
          {sublabel && <span className="text-[11px] text-slate-500">{sublabel}</span>}
        </div>
      )}
    </label>
  );
};

export const TableCheckbox: React.FC<{
  checked: boolean;
  onChange: (checked: boolean) => void;
  disabled?: boolean;
  ariaLabel?: string;
}> = ({ checked, onChange, disabled = false, ariaLabel = "Select item" }) => {
  return (
    <button
      type="button"
      aria-label={ariaLabel}
      disabled={disabled}
      onClick={(e) => {
        e.stopPropagation();
        if (!disabled) onChange(!checked);
      }}
      className={cn(
        "w-4 h-4 rounded border transition-all flex items-center justify-center cursor-pointer shrink-0 focus:outline-none focus:ring-2 focus:ring-amber-400",
        checked
          ? "bg-amber-400 border-amber-500 text-slate-950 shadow-2xs"
          : "bg-white border-slate-300 hover:border-amber-400"
      )}
    >
      {checked && <Check size={12} className="stroke-[3]" />}
    </button>
  );
};

