  const handleSaveRole = (roleData: ServiceRoleDef, permissions: Record<string, string>) => {
    const exists = customRoles.some(r => r.id === roleData.id);
    let updatedRoles: ServiceRoleDef[];
    if (exists) {
      updatedRoles = customRoles.map(r => r.id === roleData.id ? { ...r, ...roleData } : r);
      setToast({ message: `Role "${roleData.name}" permissions updated successfully!`, type: 'success' });
    } else {
      updatedRoles = [...customRoles, roleData];
      setToast({ message: `New Role "${roleData.name}" created and configured with custom permissions!`, type: 'success' });
    }
    setCustomRoles(updatedRoles);

    // Synchronize permissionMatrix for this role across all platform modules
    setPermissionMatrix(prev => {
      const nextMatrix = { ...prev };
      Object.keys(permissions).forEach(moduleName => {
        if (!nextMatrix[moduleName]) {
          nextMatrix[moduleName] = {};
        }
        nextMatrix[moduleName][roleData.name] = permissions[moduleName];
      });
      return nextMatrix;
    });

    setShowCreateRoleModal(false);
    setEditingRoleForModal(null);
  };

  const handleDeleteRole = (roleId: string) => {
    const roleToDelete = customRoles.find(r => r.id === roleId);
    if (!roleToDelete) return;
    if (!roleToDelete.isCustom) {
      setToast({ message: 'Default preset system roles cannot be deleted.', type: 'error' });
      return;
    }

    setCustomRoles(prev => prev.filter(r => r.id !== roleId));
    setToast({ message: `Custom Role "${roleToDelete.name}" deleted from system.`, type: 'info' });
  };

