      const matchStatus = statusFilter === 'All' || d.status === statusFilter;
      
      let matchVehicleTab = true;
      if (driverVehicleTab !== 'all') {
        const type = (d.type || d.vehicleCategory || '').toUpperCase();
        const vehStr = (d.vehicle || '').toLowerCase();
        if (driverVehicleTab === 'bike') {
          matchVehicleTab = type === 'BIKE' || vehStr.includes('bike') || vehStr.includes('enfield') || vehStr.includes('motorcycle');
        } else if (driverVehicleTab === 'auto') {
          matchVehicleTab = type === 'AUTO' || vehStr.includes('auto') || vehStr.includes('rickshaw');
        } else if (driverVehicleTab === 'car') {
          matchVehicleTab = type === 'CAR' || type === 'MINI' || type === 'SEDAN' || type === 'SUV' || vehStr.includes('car') || vehStr.includes('swift') || vehStr.includes('camry') || vehStr.includes('toyota') || vehStr.includes('sedan') || vehStr.includes('suv') || (!type && !vehStr.includes('bike') && !vehStr.includes('auto') && !vehStr.includes('ambulance') && !vehStr.includes('police'));
        } else if (driverVehicleTab === 'ambulance') {
          matchVehicleTab = type === 'AMBULANCE' || vehStr.includes('ambulance') || vehStr.includes('amb');
        } else if (driverVehicleTab === 'police') {
          matchVehicleTab = type === 'POLICE' || vehStr.includes('police') || vehStr.includes('patrol') || vehStr.includes('cop');
        }
      }
      
      return matchSearch && matchStatus && matchVehicleTab;
