      if (u.name && t.customerName && t.customerName.toLowerCase() === u.name.toLowerCase()) return true;
      if (u.name && t.rider && typeof t.rider === 'string' && t.rider.toLowerCase() === u.name.toLowerCase()) return true;
      if (u.phone && t.riderPhone && t.riderPhone.replace(/\s+/g, '') === u.phone.replace(/\s+/g, '')) return true;
      return false;
